<script lang="ts">
  import { onMount } from 'svelte';
  import { api, login, logout, restore, clearSession } from '$lib/api';
  import type { User } from '$lib/types';
  import Shop from '$lib/Shop.svelte'; import General from '$lib/General.svelte'; import Admin from '$lib/Admin.svelte'; import Users from '$lib/Users.svelte'; import TagihanRekap from '$lib/TagihanRekap.svelte';
  import '../app.css';
  let user: User | null = null, username = '', password = '', newPassword = '', busy = false, loading = true, error = '', view = 'dashboard', online = true, dark = false;
  let menus: {id:string; label:string; icon:string}[] = [];
  $: menus = user?.role === 'KASIR' ? [{id:'dashboard',label:'Beranda',icon:'◫'},{id:'belanja',label:'Kasir',icon:'▦'},{id:'riwayat',label:'Riwayat',icon:'◷'},{id:'profil',label:'Profil',icon:'◎'}] : user?.role === 'ANGGOTA' ? [{id:'dashboard',label:'Beranda',icon:'◫'},{id:'belanja',label:'Belanja',icon:'▦'},{id:'riwayat',label:'Transaksi saya',icon:'◷'},{id:'kartu',label:'Kartu anggota',icon:'▣'},{id:'profil',label:'Profil',icon:'◎'}] : [{id:'dashboard',label:'Beranda',icon:'◫'},{id:'users',label:'Pengguna',icon:'♙'},{id:'produk',label:'Katalog produk',icon:'▦'},{id:'kategori',label:'Kategori',icon:'▤'},{id:'urut',label:'Urutan produk',icon:'↕'},{id:'rekap',label:'Rekap anggota',icon:'◷'},{id:'tagihan-rekap',label:'Tagihan vs Rekap',icon:'⇄'},{id:'profil',label:'Profil',icon:'◎'}];
  onMount(() => { online = navigator.onLine; dark = localStorage.getItem('kopkar_theme') === 'dark'; window.addEventListener('online', connectivity); window.addEventListener('offline', connectivity); void (async () => { try { user = await restore(); } catch(e) { error = (e as Error).message; } finally { loading = false; } })(); return () => { window.removeEventListener('online', connectivity); window.removeEventListener('offline', connectivity); }; });
  function connectivity() { online = navigator.onLine; }
  async function signIn() { busy = true; error = ''; try { user = await login(username, password); password = ''; view = 'dashboard'; } catch(e) { error = (e as Error).message; } finally { busy = false; } }
  async function changePassword() { busy = true; error = ''; try { await api('/auth/ganti-password',{method:'POST',body:{password_lama:password,password_baru:newPassword}}); clearSession(); user = null; password = newPassword = ''; error = 'Password berhasil diganti. Silakan login kembali.'; } catch(e) { error = (e as Error).message; } finally { busy = false; } }
  async function signOut() { try { await logout(); } catch {} finally { user = null; view = 'dashboard'; } }
  function toggleTheme() { dark = !dark; localStorage.setItem('kopkar_theme', dark ? 'dark' : 'light'); }
</script>
<svelte:head><title>Kopkar POS</title><meta name="description" content="Aplikasi koperasi Kopkar Kusuma Lestari"/></svelte:head>
<div class:dark class="app">
{#if loading}<div class="center muted">Menyiapkan aplikasi…</div>
{:else if !user}<main class="login-page"><div class="login-story"><div class="brand inverse"><span class="brand-mark">✳</span><span>KOPKAR <small>KUSUMA LESTARI</small></span></div><div class="story-text"><p class="eyebrow light">BERSAMA TUMBUH LEBIH BAIK</p><h1>Lebih dekat<br/>dengan <em>koperasi.</em></h1><p>Akses layanan, transaksi, dan kebutuhan sehari-hari dalam satu tempat.</p></div><div class="story-footer">KOPKAR KUSUMA LESTARI <span>●</span> LAYANAN DIGITAL</div></div><div class="login-side"><div class="login-card"><div class="login-icon">✳</div><p class="eyebrow">SELAMAT DATANG</p><h2>Masuk ke akun</h2><p class="muted">Gunakan akun Kopkar Anda untuk melanjutkan.</p>{#if error}<div class="error" role="alert">{error}</div>{/if}<form on:submit|preventDefault={signIn}><label>Username<input bind:value={username} autocomplete="username" required placeholder="Masukkan username"/></label><label>Password<input type="password" bind:value={password} autocomplete="current-password" required placeholder="Masukkan password"/></label><button class="primary wide" disabled={busy}>{busy ? 'Memproses…' : 'Masuk'} <span>→</span></button></form><p class="login-help">Mengalami kendala? Hubungi administrator koperasi.</p></div></div></main>
{:else if user.ganti_password}<div class="center"><section class="panel password-card"><p class="eyebrow">KEAMANAN AKUN</p><h2>Buat password baru</h2><p>Anda perlu mengganti password sementara sebelum melanjutkan.</p>{#if error}<div class="error">{error}</div>{/if}<form on:submit|preventDefault={changePassword}><label>Password saat ini<input type="password" bind:value={password} required/></label><label>Password baru<input type="password" bind:value={newPassword} required/></label><button class="primary wide" disabled={busy}>Ganti password</button></form><button on:click={signOut}>Keluar</button></section></div>
{:else}<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">✳</span><span>KOPKAR <small>KUSUMA LESTARI</small></span></div><div class="sidebar-label">MENU UTAMA</div><nav>{#each menus as m}<button class:current={view === m.id} on:click={() => view = m.id}><span>{m.icon}</span>{m.label}</button>{/each}</nav><div class="sidebar-bottom"><button on:click={toggleTheme}>{dark ? '☀ Mode terang' : '◐ Mode gelap'}</button><button on:click={signOut}>↪ Keluar</button><div class="sidebar-note">KOPERASI KARYAWAN<br/><strong>Kusuma Lestari</strong></div></div></aside><div class="main-area"><header class="topbar"><div><span class="top-caption">KOPKAR / {user.role}</span><strong>{menus.find(m => m.id === view)?.label}</strong></div><div class="top-user"><span class="avatar">{user.nama.slice(0,1).toUpperCase()}</span><div><strong>{user.nama}</strong><small>{user.role}</small></div></div></header>{#if !online}<div class="offline">Koneksi terputus. Transaksi memerlukan koneksi internet.</div>{/if}<main class="content">{#if view === 'belanja'}<Shop {user}/>{:else if user.role === 'ADMIN' && view === 'users'}<Users/>{:else if user.role === 'ADMIN' && view === 'tagihan-rekap'}<TagihanRekap/>{:else if user.role === 'ADMIN' && ['produk','kategori','urut','rekap'].includes(view)}<Admin {view}/>{:else}<General {user} {view}/>{/if}</main></div><nav class="mobile-nav">{#each menus as m}<button class:current={view === m.id} on:click={() => view = m.id}><span>{m.icon}</span><small>{m.label}</small></button>{/each}<button on:click={signOut}><span>↪</span><small>Keluar</small></button></nav></div>{/if}
</div>
